<?php

declare(strict_types=1);

use App\Http\Controllers\Api\TokenController;
use App\Http\Controllers\Auth\ForgotPasswordController;
use App\Http\Controllers\Auth\LoginController;
use App\Http\Controllers\Auth\RegisterController;
use App\Http\Controllers\Auth\ResetPasswordController;
use App\Http\Middleware\Authenticate;
use App\Http\Middleware\RedirectIfAuthenticated;
use Sahil\Routing\Link;

/**
 * Authentication and dashboard routes, generated by `php sahil unda:auth`.
 *
 * App\Providers\WebRoutesProvider loads this file after routes/web.php. The
 * guest routes are wrapped in RedirectIfAuthenticated; the form endpoints
 * validate input, call the framework's auth services, and redirect.
 */
return [
    Link::get('/login', [LoginController::class, 'showLoginForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('login'),
    Link::post('/login', [LoginController::class, 'login'])
        ->middleware(RedirectIfAuthenticated::class)
        ->middleware('throttle:login')
        ->name('login.store'),

    // API tokens: management behind the session guard; /api/user behind
    // the bearer `auth:api` guard — no session, no redirect, JSON 401.
    Link::post('/api/tokens', [TokenController::class, 'store'])
        ->middleware(Authenticate::class)
        ->name('api.tokens.store'),
    Link::get('/api/tokens', [TokenController::class, 'index'])
        ->middleware(Authenticate::class)
        ->name('api.tokens.index'),
    Link::delete('/api/tokens/{id}', [TokenController::class, 'destroy'])
        ->middleware(Authenticate::class)
        ->name('api.tokens.destroy'),
    Link::get('/api/user', [TokenController::class, 'me'])
        ->middleware('auth:api')
        ->name('api.user'),

    Link::get('/register', [RegisterController::class, 'showRegistrationForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('register'),
    Link::post('/register', [RegisterController::class, 'register'])
        ->middleware(RedirectIfAuthenticated::class)
        ->middleware('throttle:register')
        ->name('register.store'),

    Link::get('/forgot-password', [ForgotPasswordController::class, 'showLinkRequestForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.request'),
    Link::post('/forgot-password', [ForgotPasswordController::class, 'sendResetLinkEmail'])
        ->middleware(RedirectIfAuthenticated::class)
        ->middleware('throttle:password.reset')
        ->name('password.email'),

    Link::get('/reset-password/{token}', [ResetPasswordController::class, 'showResetForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.reset'),
    Link::post('/reset-password', [ResetPasswordController::class, 'reset'])
        ->middleware(RedirectIfAuthenticated::class)
        ->middleware('throttle:password.reset')
        ->name('password.update'),

    Link::post('/logout', [LoginController::class, 'logout'])
        ->middleware(Authenticate::class)
        ->name('logout'),

    Link::get('/dashboard', [LoginController::class, 'showDashboard'])
        ->middleware(Authenticate::class)
        ->middleware('ability:access-dashboard')
        ->name('dashboard'),
];
